// Valida o corpo antes de gastar cota do Gemini. Sem download de URLs: evita SSRF.
const body = $json.body && typeof $json.body === 'object' ? $json.body : {};
const MAX_B64 = 12 * 1024 * 1024; // ~9 MB binario por imagem
const isB64 = (s) => typeof s === 'string' && s.length > 100 && s.length < MAX_B64 && /^[A-Za-z0-9+/=\r\n]+$/.test(s.slice(0, 2000));
const strip = (s) => String(s || '').replace(/^data:image\/[a-zA-Z0-9.+-]+;base64,/i, '').trim();

const jobId = String(body.jobId || '').trim();
const names = Array.isArray(body.names) ? body.names.map((n) => String(n || '').trim()).slice(0, 3) : [];
const masterBase64 = strip(body.masterBase64);
const selfieBase64 = strip(body.selfieBase64);
const jerseyBase64 = strip(body.jerseyBase64);

const errors = [];
if (!/^[a-zA-Z0-9_-]{3,32}$/.test(jobId)) errors.push('jobId');
if (names.length !== 3 || names.some((n) => !n || n.length > 24)) errors.push('names');
if (!isB64(masterBase64)) errors.push('masterBase64');
if (!isB64(selfieBase64)) errors.push('selfieBase64');
if (!isB64(jerseyBase64)) errors.push('jerseyBase64');

return [{
  json: {
    valid: errors.length === 0,
    errors,
    jobId,
    names,
    retrySeat1: body.retrySeat1 === true,
    masterBase64,
    selfieBase64,
    jerseyBase64,
    startedAt: Date.now()
  }
}];

// Modelo fixo no servidor: o app nao escolhe modelo nem prompt.
const MODEL = 'gemini-nano-banana-2.1';
const PROMPT_B = "EDIT: In Image 1, there are four empty glossy green stadium seats in the front row between two red edge seats. Seat one adult person ONLY in Seat 1 on the far left (the green seat immediately next to the red seat on the left border, directly in front of the cheering man in the plain white t-shirt, centered at x=17% and strictly within x=5% to x=26%). Seats 2, 3 and 4 to the right MUST stay 100% empty, uncovered and untouched.\nSOURCE: Image 2 supplies the foreground person's exact identity only; ignore its background, other people, original clothing, lighting and framing. Image 3 supplies the green football shirt only; ignore its white background.\nIDENTITY LOCK: Treat Image 2 as strict biometric identity evidence, not inspiration. Preserve exact gender presentation, skin tone, facial proportions, eye shape and spacing, nose, mouth, jawline, facial hair if present, hairline, full hair length, curl pattern and hair volume, apparent age and natural skin texture, with matching neck and arm skin tone. Do not beautify, lighten or darken skin tone, alter hair texture, or substitute a similar person.\nSCALE AND POSE LOCK: Match the exact head and shoulder scale of the fans standing immediately behind the green seats so the person fits compactly inside Seat 1 alone (never oversized across two seats). Seated upright facing the camera inside Seat 1, both knees and thighs kept together strictly within Seat 1, the person's right fist (on the viewer's far left, near the left border) raised in celebration, and the person's left arm tucked close to their own torso with the left hand resting on their own left thigh inside x<=25% so no elbow, forearm or shirt crosses into Seat 2 (in front of the striped red-and-black shirt). Plain dark trousers, warm authentic open smile.\nPRODUCT LOCK: Reproduce the green football shirt from Image 3 with its exact dark green color, vertical white lettering, starball and shield crests, and red-and-white collar and sleeve trims fitted naturally. Do not redesign or invent text.\nPRESERVE: Camera, crop, Brazilian crowd in European club shirts behind, lighting and colors of Image 1. Seats 2, 3 and 4 on the right keep their clean glossy green backrests and red stars completely visible and unobstructed.\nINTEGRATE: Match the cool stadium floodlight from the upper front left with realistic contact shadows on Seat 1 and natural highlights on hair, skin and jersey.\nAVOID: Never place the person in Seat 2, 3 or 4. Never spread knees or elbows into Seat 2. No text or names added to any seat. No second person from Image 2. Nothing held in the hands.";
const RETRY_PREFIX = "CRITICAL CORRECTION: Seat the person ONLY in the 1st leftmost green chair right next to the left-edge red seat, directly in front of the white t-shirt fan. Keep the 2nd, 3rd and 4th green chairs 100% empty. ";

const prompt = ($json.retrySeat1 ? RETRY_PREFIX : '') + PROMPT_B;

return [{
  json: {
    jobId: $json.jobId,
    startedAt: $json.startedAt,
    retrySeat1: $json.retrySeat1,
    model: MODEL,
    geminiBody: {
      contents: [{
        role: 'user',
        parts: [
          { text: prompt },
          { inline_data: { mime_type: 'image/jpeg', data: $json.masterBase64 } },
          { inline_data: { mime_type: 'image/jpeg', data: $json.selfieBase64 } },
          { inline_data: { mime_type: 'image/png', data: $json.jerseyBase64 } }
        ]
      }],
      generationConfig: {
        responseModalities: ['IMAGE'],
        imageConfig: { aspectRatio: '4:5', imageSize: '1K' },
        thinkingConfig: { thinkingLevel: 'HIGH' }
      }
    }
  }
}];

const meta = $('Montar Requisicao Gemini').first().json;
const candidate = $json?.candidates?.[0];
const finishReason = String(candidate?.finishReason || '');
const parts = candidate?.content?.parts || [];
let foundData = null;
for (const p of parts) {
  const inline = p?.inlineData || p?.inline_data;
  if (inline?.data) { foundData = inline.data; break; }
}
const upstreamError = $json?.error ? String($json.error.status || $json.error.code || 'UPSTREAM_ERROR') : '';
const errText = JSON.stringify($json?.error || '').toLowerCase();
const modelRefused =
  ['SAFETY', 'IMAGE_SAFETY', 'PROHIBITED_CONTENT', 'RECITATION'].includes(finishReason) ||
  errText.includes('safety');

// Nunca devolve o corpo bruto do Google: so o que o app precisa.
return [{
  json: {
    ok: Boolean(foundData) && !modelRefused,
    jobId: meta.jobId,
    retrySeat1: Boolean(meta.retrySeat1),
    finishReason: finishReason || upstreamError,
    modelRefused,
    composedImageBase64: modelRefused ? null : foundData,
    durationMs: Math.max(0, Date.now() - Number(meta.startedAt || Date.now())),
    model: meta.model,
    imageSize: '1K',
    orchestrator: 'n8n-cloud'
  }
}];
